package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.Dues;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;

/** The sheet's figures at one moment, as the screen shows them: each person's claimed and
 *  due-total (null: n/a), in the order they were added, and the sheet's claimed-total and due-total. */
public record Rollup(Map<Long, Figures> people, String claimedTotal, String dueTotal) {

    /** A person's figures: their name, claimed and due-total (null: n/a). */
    public record Figures(String name, String claimed, String dueTotal) {
        public boolean sameAs(Figures other) {
            return other != null && claimed.equals(other.claimed)
                    && (dueTotal == null ? other.dueTotal == null : dueTotal.equals(other.dueTotal));
        }
    }

    /** The sheet's figures now. */
    public static Rollup of(String sheetId, PersonRepository people, ClaimRepository claims,
            RateRepository rates, SheetRepository sheets, SettingRepository settings) {
        List<Rate> sheetRates = rates.list(sheetId);
        String floor = settings.floor(sheetId);
        LocalDate todayDate = sheets.today(sheetId);
        String today = todayDate.toString();
        Dues.Late late = settings.late(sheetId, todayDate);
        List<Claim> all = claims.list(sheetId);
        Map<Long, Figures> figures = new LinkedHashMap<>();
        BigDecimal claimedTotal = zero();
        BigDecimal dueTotal = zero();
        for (Person p : people.list(sheetId)) {
            BigDecimal claimed = zero();
            BigDecimal due = zero();
            boolean kept = false;
            for (Claim c : all) {
                if (c.getPersonId() != p.getId() || !p.countsLive(c)) continue;
                claimed = claimed.add(new BigDecimal(c.getAmount()));
                String grade = p.gradeOn(c.getDate());
                String pct = rateOn(sheetRates, grade, c.getDate());
                String d = Dues.shown(c, pct == null ? null : Dues.of(c.getAmount(), pct, floor, late.rounding(c.getRoundDate())), late);
                kept |= c.getSettledDue() != null || c.isBound()
                        || (pct != null && !grade.equals(p.getGrade()));
                if (d != null) due = due.add(new BigDecimal(d));
            }
            boolean na = rateOn(sheetRates, p.getGrade(), today) == null && !kept;
            figures.put(p.getId(), new Figures(p.getName(), claimed.toPlainString(),
                    na ? null : due.toPlainString()));
            claimedTotal = claimedTotal.add(claimed);
            if (!na) dueTotal = dueTotal.add(due);
        }
        return new Rollup(figures, claimedTotal.toPlainString(), dueTotal.toPlainString());
    }

    /** The audit lines after a change from {@code before} to this: one ROLLUP per person whose
     *  figures moved (a new person counts as moved), then TOTALS when a sheet total moved. */
    public List<String> changesSince(Rollup before, String sheetId, String by) {
        String head = " sheet=" + sheetId + " by=" + by;
        List<String> lines = new ArrayList<>();
        people.forEach((id, now) -> {
            if (!now.sameAs(before.people.get(id))) {
                lines.add("ROLLUP" + head + " person=" + now.name() + " claimed=" + now.claimed()
                        + " due-total=" + (now.dueTotal() == null ? "n/a" : now.dueTotal()));
            }
        });
        if (!claimedTotal.equals(before.claimedTotal) || !dueTotal.equals(before.dueTotal)) {
            lines.add("TOTALS" + head + " claimed-total=" + claimedTotal + " due-total=" + dueTotal);
        }
        return lines;
    }

    /** The grade's rate in force on the date (yyyy-MM-dd): the one with the latest from-date on or
     *  before it; null when there is none. */
    private static String rateOn(List<Rate> rates, String grade, String date) {
        Rate found = null;
        for (Rate r : rates) {
            if (!r.grade().equals(grade) || (r.from() != null && r.from().compareTo(date) > 0)) continue;
            if (found == null || nz(found.from()).compareTo(nz(r.from())) < 0) found = r;
        }
        return found == null ? null : found.pct();
    }

    private static String nz(String from) {
        return from == null ? "" : from;
    }

    private static BigDecimal zero() {
        return BigDecimal.ZERO.setScale(2);
    }
}
package net.officefloor.hq.app.claim;

/** A claim's status. It starts DRAFT; DRAFT opens to OPEN, OPEN settles to SETTLED (or, settled by a
 *  clerk above the clerk limit, to PENDING), PENDING is approved to SETTLED or rejected back to OPEN,
 *  and DRAFT, OPEN or PENDING voids to VOID. SETTLED and VOID are final. */
public enum ClaimStatus {
    DRAFT, OPEN, PENDING, SETTLED, VOID;

    /** The status after moving to {@code to}; refused when this status does not allow it. */
    public ClaimStatus moveTo(ClaimStatus to) throws ClaimStatusException {
        boolean allowed = switch (to) {
            case OPEN -> this == DRAFT || this == PENDING;
            case PENDING -> this == OPEN;
            case SETTLED -> this == OPEN || this == PENDING;
            case VOID -> this == DRAFT || this == OPEN || this == PENDING;
            case DRAFT -> false;
        };
        if (!allowed) {
            throw new ClaimStatusException("A " + this + " claim cannot become " + to);
        }
        return to;
    }

    /** Whether a claim with this status is open: OPEN, or PENDING (awaiting a steward's approval). */
    public static boolean isOpen(String status) {
        return OPEN.name().equals(status) || PENDING.name().equals(status);
    }

    /** The audit event recorded when a claim moves to this status. */
    public String event() {
        return switch (this) {
            case OPEN -> "CLAIM_OPENED";
            case PENDING -> "CLAIM_PENDING";
            case SETTLED -> "CLAIM_SETTLED";
            case VOID -> "CLAIM_VOIDED";
            case DRAFT -> "CLAIM_DRAFTED";
        };
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.period.PeriodClosedException;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.Role;
import net.officefloor.hq.app.setting.RoleRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Approves a PENDING claim: it becomes SETTLED, its due fixed at the figure it shows at that moment
 *  (its live figure, a statement does not bind a PENDING claim, with its late charge on the sheet's
 *  today). Refused unless the user is a steward, and for the user who opened it. */
public class ApproveClaim {
    public void move(@RequestParam(name = "by", required = false) String by, @Val Claim claim,
            PersonRepository people, RateRepository rates, PeriodRepository periods,
            RoleRepository roles, SettingRepository settings, SheetRepository sheets)
            throws ClaimStatusException, PeriodClosedException {
        periods.requireOpen(claim.getSheetId(), claim.getDate());
        String user = by == null ? "" : by;
        if (!ClaimStatus.PENDING.name().equals(claim.getStatus())) {
            throw new ClaimStatusException("A " + claim.getStatus() + " claim cannot be approved");
        }
        if (!Role.STEWARD.equals(roles.roleOf(claim.getSheetId(), user))) {
            throw new ClaimStatusException("Only a steward can approve a claim");
        }
        if (claim.getOpenedBy() != null && claim.getOpenedBy().equals(user)) {
            throw new ClaimStatusException("The user who opened a claim cannot approve it");
        }
        Person person = people.find(claim.getSheetId(), claim.getPersonId());
        Rate rate = person == null ? null : rates.find(claim.getSheetId(), person.gradeOn(claim.getDate()),
                LocalDate.parse(claim.getDate()));
        Dues.Late late = settings.late(claim.getSheetId(), sheets.today(claim.getSheetId()));
        String due = Dues.shown(claim, rate == null ? null : Dues.of(claim.getAmount(), rate.pct(),
                settings.floor(claim.getSheetId()), late.rounding(claim.getRoundDate())), late);
        claim.setStatus(ClaimStatus.PENDING.moveTo(ClaimStatus.SETTLED).name());
        claim.setSettledDue(due);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.period.PeriodClosedException;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.setting.Role;
import net.officefloor.hq.app.setting.RoleRepository;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Rejects a PENDING claim with a reason: it goes back to OPEN, bound again by its person's last
 *  statement when that statement bound it. Refused unless the user is a steward, and without a reason. */
public class RejectClaim {
    public void move(@RequestParam(name = "by", required = false) String by,
            @RequestParam(name = "reason", required = false) String reason, @Val Claim claim,
            PeriodRepository periods, RoleRepository roles)
            throws ClaimStatusException, InvalidClaimException, PeriodClosedException {
        periods.requireOpen(claim.getSheetId(), claim.getDate());
        if (!ClaimStatus.PENDING.name().equals(claim.getStatus())) {
            throw new ClaimStatusException("A " + claim.getStatus() + " claim cannot be rejected");
        }
        if (!Role.STEWARD.equals(roles.roleOf(claim.getSheetId(), by == null ? "" : by))) {
            throw new ClaimStatusException("Only a steward can reject a claim");
        }
        if (reason == null || reason.isBlank()) {
            throw new InvalidClaimException("A rejection needs a reason");
        }
        claim.setStatus(ClaimStatus.PENDING.moveTo(ClaimStatus.OPEN).name());
