                    : c.status === 'SETTLED' || c.status === 'VOID'
                    ? `A ${c.status} claim cannot be reassigned.`
                    : 'Only a steward can reassign a claim, and only to another person.'}</span>
                )}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
